-- Staging: carga cruda de las 45 filas del Excel. No toca la tabla jugadores.
create table if not exists import_staging (
  lote        text not null,
  n           int  not null,
  nombre_raw  text,
  nombres     text,
  apellidos   text,
  rut         text,
  rut_valido  boolean,
  fecha_nac   date,
  anio_nac    int,
  origen_fecha text,
  categoria   text,
  codigo      text,
  jugador_id  text,
  veredicto   text,
  codigo_match text,
  primary key (lote, n)
);
delete from import_staging where lote = 'lote-2026-09-02-lista-futbol';

select veredicto, count(*) from import_staging where lote='lote-2026-09-02-lista-futbol' group by 1 order by 1;